"""One physical view bank/clock, no silent cross-view attachment fallback."""
from pathlib import Path
import base64,json
P=Path(__file__).resolve().parent;ROOT=P.parents[2]
data={'parts':json.loads((P/'parts.json').read_text())['parts'],'source':json.loads((P/'source/source.json').read_text()),'images':{}}
for row in data['parts']:
 data['images'][row['name']]='data:image/png;base64,'+base64.b64encode((ROOT/row['file']).read_bytes()).decode()
data['source_images']=['data:image/png;base64,'+base64.b64encode((ROOT/r['path']).read_bytes()).decode() for r in data['source']['frames']]
html='''<!doctype html><meta charset="utf-8"><title>Pickup / physical view B</title><style>body{background:#1d2935;color:#eef1fc;font:16px system-ui;margin:24px}section{display:flex;gap:12px;flex-wrap:wrap}canvas{width:384px;height:512px;background:#283747}button,input,select{font:inherit}p{max-width:900px}</style><h1>Physical view B / pickup</h1><section><div><p>Actual source / owner colors</p><img id="source" width="384" height="512"></div><div><p>Generated separate parts / source-driven motion</p><canvas id="view" width="384" height="512"></canvas></div></section><p><select id="style"><option value="original">Generated combined head</option><option value="silver">Separate silver hair</option><option value="bald">Complete base head</option></select><input id="frame" type="range" min="0" max="7" value="0"><select id="clock"><option value="game">Game / 700ms</option><option value="source">Source / 1300ms</option></select><button id="play">Play once</button><label><input id="bones" type="checkbox">Authored joints</label></p><p id="status"></p><script>__BASE__</script><script>__VIEW__</script><script>
const DATA=__DATA__,images={},poses=DATA.source.frames.map((_,i)=>ViewPickup.pose(DATA.source,i));let ready=false,index=0,style='original',running=false,start=0;const ctx=document.getElementById('view').getContext('2d');
Promise.all(Object.entries(DATA.images).map(([n,src])=>new Promise(resolve=>{const im=new Image;im.onload=()=>{if(n==='head.base'){const c=document.createElement('canvas');c.width=im.width;c.height=im.height;const x=c.getContext('2d');x.drawImage(im,0,0);const d=x.getImageData(0,0,c.width,c.height);for(let k=3;k<d.data.length;k+=4)if(d.data[k]>=240)d.data[k]=255;x.putImageData(d,0,0);images[n]=c}else images[n]=im;resolve()};im.src=src}))).then(()=>{ready=true;draw()});
function rows(i,s=style){return ViewPickup.rows(DATA.parts,poses[i],s)}
function draw(){if(!ready)return;ModularPickup.render(ctx,rows(index),images,document.getElementById('bones').checked);document.getElementById('source').src=DATA.source_images[index];document.getElementById('frame').value=index;document.getElementById('style').value=style;document.getElementById('status').textContent='View B / '+style+' / frame '+(index+1)+' / '+poses[index].source_time_seconds.toFixed(3)+'s'}
document.getElementById('frame').oninput=e=>{running=false;index=+e.target.value;draw()};document.getElementById('style').onchange=e=>{style=e.target.value;draw()};document.getElementById('bones').onchange=draw;document.getElementById('clock').onchange=()=>{running=false;index=0;draw()};
function tick(t){if(!running)return;const elapsed=t-start,game=document.getElementById('clock').value==='game',active=game?700:1300;while(index<7&&(game?(index+1)*100:poses[index+1].source_time_seconds*1000)<=elapsed)index++;draw();if(elapsed>=active+600){running=false;return}requestAnimationFrame(tick)}document.getElementById('play').onclick=()=>{index=0;running=true;start=performance.now();requestAnimationFrame(tick)};
window.viewB={get ready(){return ready},get running(){return running},get index(){return index},poses,data:DATA,rows,select(s,i=index){style=s;index=i;draw()},frame(i,s='original',bones=false){ModularPickup.render(ctx,rows(i,s),images,bones);return ctx.canvas.toDataURL('image/png')},headFrame(i,s){ModularPickup.render(ctx,rows(i,s).filter(r=>r.name.startsWith('head')||r.name.startsWith('hair.')),images,false);return ctx.canvas.toDataURL('image/png')},partFrame(i,name){ModularPickup.render(ctx,rows(i,'silver').filter(r=>r.name===name),images,false);return ctx.canvas.toDataURL('image/png')}};
</script>'''
(P/'view-preview.html').write_text(html.replace('__BASE__',(P.parent/'pickup-modular-v32/rig-runtime.js').read_text()).replace('__VIEW__',(P/'view-runtime.js').read_text()).replace('__DATA__',json.dumps(data,separators=(',',':')).replace('<','\\u003c')))
